import Foundation
import SwiftData
import SwiftUI

struct SteamGame: Codable, Equatable {
    var appid: Int
    var name: String
    var img_icon_url: String?
    var playtime_forever: Int
    var playtime_windows_forever: Int
    var playtime_mac_forever: Int
    var playtime_linux_forever: Int
    var playtime_deck_forever: Int
    var rtime_last_played: Int
}

struct SteamGamesResumed: Codable, Equatable {
    var appid: Int
    var name: String
    var img_icon_url: String?
}

enum FilterTypes: String {
    case alphabetical
    case most_played
    case least_played
    case recent_played
    
    func getName() -> String {
        switch self {
        case .alphabetical:
            "Alphabetically"
        case .most_played:
            "Most played"
        case .least_played:
            "Least played"
        case .recent_played:
            "Recent games"
        }
    }
    
    func getImage() -> String {
        switch self {
        case .alphabetical:
            "textformat.characters"
        case .most_played:
            "hourglass.tophalf.filled"
        case .least_played:
            "hourglass.bottomhalf.filled"
        case .recent_played:
            "gamecontroller.fill"
        }
    }
}


